### 4. Detecting Pending Pods and Triggering Scaling via Kubernetes API

**Using the Kubernetes API to detect unschedulable pods:**

```go
import (
    metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
    "k8s.io/apimachinery/pkg/fields"
)

// Method 1: Field selector (efficient, server-side filtering)
func getUnschedulablePods(ctx context.Context, clientset kubernetes.Interface) ([]corev1.Pod, error) {
    // Field selector for phase=Pending
    fieldSelector := fields.Set{"status.phase": "Pending"}.String()

    pods, err := clientset.CoreV1().Pods("").List(ctx, metav1.ListOptions{
        FieldSelector: fieldSelector,
    })
    if err != nil {
        return nil, err
    }

    var unschedulable []corev1.Pod
    for _, pod := range pods.Items {
        for _, cond := range pod.Status.Conditions {
            if cond.Type == corev1.PodScheduled && 
               cond.Status == corev1.ConditionFalse && 
               cond.Reason == "Unschedulable" {
                unschedulable = append(unschedulable, pod)
            }
        }
    }
    return unschedulable, nil
}

// Method 2: Watch for real-time detection
func watchPendingPods(ctx context.Context, clientset kubernetes.Interface, scaleFn func(int)) {
    watcher, err := clientset.CoreV1().Pods("").Watch(ctx, metav1.ListOptions{
        FieldSelector: fields.Set{"status.phase": "Pending"}.String(),
    })
    if err != nil {
        panic(err)
    }

    ch := watcher.ResultChan()
    for event := range ch {
        pod, ok := event.Object.(*corev1.Pod)
        if !ok {
            continue
        }

        // Check if this pod is unschedulable
        for _, cond := range pod.Status.Conditions {
            if cond.Type == corev1.PodScheduled && 
               cond.Reason == "Unschedulable" {
                // Get total unschedulable count and trigger scaling
                count := getUnschedulableCount(ctx, clientset)
                scaleFn(count)
            }
        }
    }
}
```

**Key insight:** The Cluster Autoscaler uses a "simulation" approach — it simulates scheduling pending pods onto new nodes to determine exactly how many nodes to add. For a custom scaler, you can use the `schedulerframework` package:

```go
import "k8s.io/kubernetes/pkg/scheduler/framework"

// Simulate scheduling to determine node deficit
func calculateNodeDeficit(ctx context.Context, clientset kubernetes.Interface, 
    pendingPods []*corev1.Pod, existingNodes []*corev1.Node) int {

    // Create a node info map
    nodeInfoMap := make(map[string]*framework.NodeInfo)
    for _, node := range existingNodes {
        ni := framework.NewNodeInfo()
        ni.SetNode(node)
        nodeInfoMap[node.Name] = ni
    }

    // Try to schedule each pending pod
    remainingPods := 0
    for _, pod := range pendingPods {
        scheduled := false
        for _, ni := range nodeInfoMap {
            // Check if pod fits on this node
            if fitsNode(pod, ni) {
                ni.AddPod(pod)
                scheduled = true
                break
            }
        }
        if !scheduled {
            remainingPods++
        }
    }

    // Calculate how many nodes needed (assuming a node capacity)
    return int(math.Ceil(float64(remainingPods) / float64(podsPerNode)))
}
