### 5. Implementing a Forecasting Service Inside Kubernetes

**Architecture: A sidecar or separate Deployment that exposes a gRPC/REST API.**

```go
// Forecasting service (runs as a Deployment in the cluster)
type ForecastingService struct {
    // Stores time-series metrics
    metricsStore *InMemoryTimeSeries

    // The forecasting model
    model *prophet.Prophet  // or Holt-Winters, ARIMA, etc.
}

// API exposed to the scaler
type PredictorServer struct {
    forecasting *ForecastingService
}

func (s *PredictorServer) GetPrediction(ctx context.Context, req *PredictionRequest) (*PredictionResponse, error) {
    // 1. Fetch historical metrics from Prometheus
    metrics, err := s.fetchHistoricalMetrics(ctx, req.MetricQuery, req.LookbackWindow)

    // 2. Train or update the model
    model := prophet.New(prophet.WithDailySeasonality(), prophet.WithWeeklySeasonality())
    model.Fit(metrics)

    // 3. Forecast future values
    future := model.MakeFutureDataframe(req.ForecastHorizon)
    forecast := model.Predict(future)

    // 4. Return predicted resource demand
    return &PredictionResponse{
        PredictedPodCount:    int32(forecast.Yhat[len(forecast.Yhat)-1]),
        PredictedCPU:         forecast.Yhat,
        ConfidenceInterval:   forecast.YhatUpper,
        ForecastTimestamps:   forecast.Dates,
    }, nil
}

// gRPC service definition
// service Predictor {
//   rpc GetPrediction(PredictionRequest) returns (PredictionResponse);
//   rpc GetNodeCountRecommendation(NodeCountRequest) returns (NodeCountResponse);
// }

// message PredictionRequest {
//   string metric_query = 1;       // e.g., "sum(rate(pod_cpu_usage[5m]))"
//   string lookback_window = 2;    // e.g., "720h" (30 days)
//   string forecast_horizon = 3;   // e.g., "2h"
// }
```

**Feeding predictions to the scaler:**

```go
// In the scaler controller:
type PredictiveNodeScaler struct {
    predictorClient pb.PredictorClient  // gRPC client to forecasting service
    cloudScaler     CloudNodeScaler
}

func (s *PredictiveNodeScaler) reconcile(ctx context.Context) error {
    // Get current state
    pendingPods := getUnschedulablePods(ctx, s.k8sClient)
    currentNodes := getReadyNodeCount(ctx, s.k8sClient)

    // Get prediction
    predResp, err := s.predictorClient.GetNodeCountRecommendation(ctx, &pb.NodeCountRequest{
        MetricQuery:    "sum(kube_pod_container_resource_requests_cpu_cores)",
        LookbackWindow: "720h",
        ForecastHorizon: "1h",
    })

    // Combine reactive (pending pods) + proactive (prediction)
    reactiveNodes := calculateNodesForPods(pendingPods)
    proactiveNodes := predResp.RecommendedNodeCount

    desiredNodes := max(reactiveNodes, proactiveNodes)
    desiredNodes = clamp(desiredNodes, s.minNodes, s.maxNodes)

    if desiredNodes != currentNodes {
        return s.cloudScaler.SetNodePoolSize(ctx, s.nodePoolID, desiredNodes)
    }
    return nil
}
```

